import java.util.*;

public class Main {

    public static void main(String args[]){
        Scanner scanner = new Scanner(System.in);
        int base = scanner.nextInt();
        int number = scanner.nextInt();
        int digits[] = new int[101];

        for(int index=0; index<=100; index++){
            digits[index] = number % base;
            number /= base;
        }

        int carryFlag = 0;
        boolean validNumber = true;
        for(int index=0; index<=100; index++){
            digits[index] += carryFlag;
            carryFlag = digits[index] / base;
            digits[index] %= base;

            if(digits[index] == 0 || digits[index] == 1){
                continue;
            } else if(digits[index] == base - 1){
                carryFlag = 1;
            } else {
                validNumber = false;
                break;
            }
        }

        System.out.print((validNumber && carryFlag != 1) ? "YES" : "NO");
    }
}
